function quoteEconomics(values,capacity=Infinity){const keys=['tonnes','sell','buy','freight','other'];if(keys.some(k=>String(values[k]??'').trim()===''||!Number.isFinite(Number(values[k]))))return null;const v=Object.fromEntries(keys.map(k=>[k,Number(values[k])]));if(v.tonnes<=0||v.tonnes>capacity||['sell','buy','freight','other'].some(k=>v[k]<0||v[k]>1e9))return null;const unit=v.sell-v.buy-v.freight-v.other;if(!Number.isFinite(unit*v.tonnes))return null;return{...v,unit,total:Math.round(unit*v.tonnes*100)/100}}
