const badge=(s)=>`<span class="pill ${/risk|review|requested|unconfirmed|Pending|Discrepancy/i.test(s)?'amber':/transit|Loading/i.test(s)?'blue':/Draft|Booked/i.test(s)?'gray':''}">${esc(s)}</span>`;
const btn=(label,action,cls='',ico='')=>`<button type="button" class="btn ${esc(cls)}" data-action="${esc(action)}">${ico?icon(ico,15):''}${label}</button>`;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3300)}
