function head(title,sub,actions=''){return `<div class="pagehead"><div><h1>${title}</h1><p class="sub">${sub}</p></div>${actions?`<div class="actions">${actions}</div>`:''}</div>`}
function metric(label,value,unit,foot,ico){return `<div class="metric"><div class="label">${label}${icon(ico,17)}</div><div class="number">${value}<span>${unit}</span></div><div class="foot">${foot}</div></div>`}
