function opportunityTable(lots){return `<div class="table-wrap"><table><thead><tr><th>Commodity / source</th><th>Delivery lane</th><th>Available</th><th>Contribution / t</th><th>Readiness</th><th></th></tr></thead><tbody>${lots.map(l=>`<tr><td><div class="cell-main"><span class="commodity ${esc(l.color)}">${icon('grain',17)}</span><span><strong>${esc(l.commodity)}</strong><small>${esc(l.supplier)}</small></span></div></td><td>${esc(l.from)} <span class="muted">→</span> ${esc(l.to)}<small>${esc(l.date)} · ${esc(l.lane)}</small></td><td>${num(lotAvailable(l))} t</td><td><strong class="positive">${money(l.sell-l.buy-l.freight-l.other,2)}</strong></td><td>${badge(l.status)}</td><td><button class="icon-btn" aria-label="Review ${esc(l.id)}" data-action="quote:${esc(l.id)}">${icon('arrow',16)}</button></td></tr>`).join('')}</tbody></table></div>`}
