document.addEventListener('click',e=>{const b=e.target.closest('[data-action],[data-page],[data-filter]');if(!b)return;if(b.dataset.page)go(b.dataset.page);else if(b.dataset.filter){filter=b.dataset.filter;render()}else action(b.dataset.action)});
document.addEventListener('input',e=>{if(e.target.id==='filter-search'){const pos=e.target.selectionStart;query=e.target.value;render();const el=$('#filter-search');el.focus();el.setSelectionRange(pos,pos)}if(e.target.closest('#quote-form')){const f=$('#quote-form');const d=Object.fromEntries(new FormData(f));const lot=state.lots.find(l=>l.id===f.dataset.id);const result=quoteEconomics(d,lot?lotAvailable(lot):0);$('#per-tonne').textContent=result?money(result.unit,2):'—';$('#total-contribution').textContent=result?money(result.total,2):'—';$('#per-tonne').classList.toggle('negative',Boolean(result&&result.unit<0));$('#total-contribution').classList.toggle('negative',Boolean(result&&result.total<0))}if(e.target.id==='global-query'){const q=e.target.value.toLowerCase().trim();let res=[...state.lots.filter(l=>JSON.stringify(l).toLowerCase().includes(q)).map(l=>['grain',l.id+' · '+l.commodity,l.supplier,'quote:'+l.id]),...state.loads.filter(l=>JSON.stringify(l).toLowerCase().includes(q)).map(l=>['truck',l.id,l.origin+' → '+l.destination,'load:'+l.id]),...state.parties.filter(p=>JSON.stringify(p).toLowerCase().includes(q)).map(p=>['users',p.name,p.type,'party:'+state.parties.indexOf(p)])].slice(0,8);$('#global-results').innerHTML=res.length?res.map(r=>`<button class="file" style="width:100%;text-align:left" data-action="${r[3]}">${icon(r[0])}<div><h3>${esc(r[1])}</h3><p>${esc(r[2])}</p></div></button>`).join(''):'<div class="empty">No matching records. Try “corn” or “Lévis”.</div>'}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f));switch(f.id){case 'settings-form':state.workspace=d.workspace;state.user=d.user;save();render();toast('Workspace preferences saved');break;case 'quote-form':{const l=state.lots.find(x=>x.id===f.dataset.id);const economics=quoteEconomics(d,l?lotAvailable(l):0);if(!l||!economics){toast('Enter valid non-negative prices and a quantity within the available lot.');break}const q={id:'DRAFT-'+String(state.quotes.length+1).padStart(3,'0'),source:l.id,commodity:l.commodity,buyer:l.buyer,tonnes:+d.tonnes,sell:+d.sell,buy:+d.buy,freight:+d.freight,other:+d.other,total:economics.total};state.quotes.unshift(q);save();close();go('book');toast('Draft saved · No stock reserved or contract sent');break}case 'opportunity-form':if(!['Corn','Soybeans','Feed wheat'].includes(d.commodity)||!quoteEconomics({...d,freight:24,other:4},100000)||!d.supplier?.trim()||!d.from?.trim()||!d.to?.trim()){toast('Check the commodity, quantity, prices and required locations.');break}state.lots.unshift({id:'OP-'+(1043+state.lots.length-6),commodity:d.commodity,grade:'Quality evidence pending',supplier:d.supplier,from:d.from,to:d.to,buyer:'Buyer to confirm',tonnes:+d.tonnes,buy:+d.buy,sell:+d.sell,freight:24,other:4,status:'Needs review',quality:'Evidence requested',lane:'Route to verify',date:'Window to confirm',color:d.commodity==='Soybeans'?'soy':d.commodity==='Corn'?'corn':'wheat'});save();close();go('opportunities');toast('Tentative opportunity saved');break;case 'reconcile-form':if(!state.accepted.includes('variance'))state.accepted.push('variance');state.resolution=d.note;save();close();render();toast('38.37 t basis approved · Original evidence retained');break;case 'followup-form':download('follow-up-draft.txt',`LOCAL DEMO DRAFT — NOT SENT\nSubject: ${d.subject}\n\n${d.message}`);close();break;case 'party-form':state.parties.push({...d,verified:false,volume:'0 t',score:'No history',initials:d.name.split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase()});save();close();go('counterparties');toast('Unverified sample passport created');break;case 'document-form':if(!state.documents)state.documents=[];state.documents.push({id:Date.now().toString(36)+'-'+state.documents.length,name:d.name,type:d.type||'Evidence record'});save();close();render();toast('Sample document record added for review');break}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();action('global-search')}if(e.key==='Escape')$('.sidebar')?.classList.remove('open')});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(nav.some(n=>n[0]===p)&&p!==page){page=p;filter='All';query='';render()}});
page=nav.some(n=>n[0]===location.hash.slice(1))?location.hash.slice(1):'today';render();
